custom_css:
/* 00-cover-fonts.css */
/* HarmonyOS Sans SC: fixed public package, npmmirror first and jsDelivr fallback. Novecento keeps its existing embedded subset. */
@font-face {
    font-family: "EF Cover Harmony Medium";
    font-style: normal;
    font-weight: 500;
    font-display: swap;
    src: url("https://registry.npmmirror.com/@lobehub/webfont-harmony-sans-sc/1.0.0/files/fonts/HarmonyOS_Sans_SC_Medium.woff2") format("woff2"),
        url("https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/fonts/HarmonyOS_Sans_SC_Medium.woff2") format("woff2");
}

@font-face {
    font-family: "EF Cover Harmony Bold";
    font-style: normal;
    font-weight: 700;
    font-display: swap;
    src: url("https://registry.npmmirror.com/@lobehub/webfont-harmony-sans-sc/1.0.0/files/fonts/HarmonyOS_Sans_SC_Bold.woff2") format("woff2"),
        url("https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/fonts/HarmonyOS_Sans_SC_Bold.woff2") format("woff2");
}

@font-face {
    font-family: "EF Cover Harmony Regular";
    font-style: normal;
    font-weight: 400;
    font-display: swap;
    src: url("https://registry.npmmirror.com/@lobehub/webfont-harmony-sans-sc/1.0.0/files/fonts/HarmonyOS_Sans_SC_Regular.woff2") format("woff2"),
        url("https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/fonts/HarmonyOS_Sans_SC_Regular.woff2") format("woff2");
}

@font-face {
    font-family: "EF Cover Novecento Medium";
    font-style: normal;
    font-weight: 400;
    font-display: swap;
    src: url("data:font/woff2;base64,") format("woff2");
}

/* 01-tokens.css */
:root {
    --ef-void: #101415;
    --ef-void-soft: #171b1c;
    /* 纸面、墨色与黄色取自官号长图实测：纸面中性白而非偏绿，黄色是纯黄。
       量法与数值见 references/UI_FACTS.md 的「官号长图实测」表。 */
    --ef-paper: #fdfdfd;
    --ef-paper-hi: #ffffff;
    --ef-workbench: #e5e5e5;
    --ef-ink: #061112;
    --ef-graphite: #25292a;
    /* 深色当前块：学官网 Button(#383838)与百科当前条目，取中间值。 */
    --ef-dark: #2b2f2e;
    --ef-muted: #707674;
    --ef-signal: #ffff0f;
    --ef-block: #444444;
    --ef-label: #888888;
    --ef-calib-m: #d025ce;
    --ef-calib-y: #fcf56d;
    --ef-calib-c: #34e3ad;
    --ef-line: rgba(23, 26, 26, 0.16);
    --ef-line-soft: rgba(23, 26, 26, 0.075);
    --ef-paper-grid: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='160' height='160' viewBox='0 0 160 160'%3E%3Cdefs%3E%3Cpattern id='g' width='10' height='10' patternUnits='userSpaceOnUse'%3E%3Cpath d='M10 0H0V10' fill='none' stroke='%23171a1a' stroke-opacity='.018' stroke-width='.55'/%3E%3C/pattern%3E%3C/defs%3E%3Crect width='160' height='160' fill='url(%23g)'/%3E%3Cg fill='none' stroke='%23171a1a'%3E%3Cpath d='M0 .5H160M.5 0V160' stroke-opacity='.025' stroke-width='.65'/%3E%3Cpath d='M74 80H86M80 74V86' stroke-opacity='.09' stroke-width='.9'/%3E%3C/g%3E%3C/svg%3E");
    --ef-gray-grid: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='160' height='160' viewBox='0 0 160 160'%3E%3Cdefs%3E%3Cpattern id='x' width='8' height='8' patternUnits='userSpaceOnUse'%3E%3Cpath d='M-2 0L8 10M8-2L-2 8' fill='none' stroke='%23434b49' stroke-opacity='.03' stroke-width='.5'/%3E%3C/pattern%3E%3C/defs%3E%3Crect width='160' height='160' fill='url(%23x)'/%3E%3Cg fill='none' stroke='%23434b49' stroke-width='.65'%3E%3Cpath d='M0 80H76M84 80H160M80 0V76M80 84V160' stroke-opacity='.075'/%3E%3Cpath d='M66 66L76 76M84 84L94 94M94 66L84 76M76 84L66 94' stroke-opacity='.11'/%3E%3C/g%3E%3Ccircle cx='80' cy='80' r='1' fill='%23434b49' fill-opacity='.14'/%3E%3C/svg%3E");
    --ef-contours: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='280' height='90' viewBox='0 0 280 90'%3E%3Cg fill='none' stroke='%23171a1a' stroke-width='.75' opacity='.18'%3E%3Cpath d='M-10 54c32-27 56-29 80-6s54 25 79 4 53-25 78-6 45 21 69 4'/%3E%3Cpath d='M-12 64c33-29 61-31 87-7s48 22 72 2 54-29 82-8 45 20 64 7'/%3E%3Cpath d='M8 75c27-24 49-24 70-5s45 19 66 2 50-28 81-11 48 21 67 11'/%3E%3Cpath d='M21 34c20-17 35-17 51-3s34 15 49 3 37-20 59-7 37 14 57 5'/%3E%3C/g%3E%3C/svg%3E");
    --ef-contours-light: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='320' height='96' viewBox='0 0 320 96'%3E%3Cg fill='none' stroke='white' stroke-width='.5' stroke-opacity='.42' stroke-linecap='round'%3E%3Cpath d='M-38 97C-6 91 2 68 23 50C43 33 65 30 82 40C97 49 108 43 123 29C136 17 143 5 162-9'/%3E%3Cpath d='M-37 88C-8 82-1 61 19 44C39 27 62 25 79 34C94 42 105 37 119 23C131 12 138 1 155-10'/%3E%3Cpath d='M-35 78C-9 73-3 54 16 38C35 22 59 20 75 28C89 35 101 31 114 18C125 8 131-2 147-11'/%3E%3Cpath d='M-32 68C-8 64-3 47 14 32C32 17 55 15 71 22C84 28 96 25 108 13C118 4 123-4 138-12'/%3E%3Cpath d='M-29 58C-7 55-2 40 13 27C29 13 51 11 66 17C78 22 89 20 101 9C110 1 115-6 128-13'/%3E%3Cpath d='M-25 48C-5 46-1 34 12 22C27 9 47 7 61 12C72 16 82 15 93 5C101-2 106-8 118-14'/%3E%3Cpath d='M101 97C124 86 131 70 151 62C171 54 187 61 204 53C222 45 226 27 246 19C267 11 284 20 302 14C316 10 326 1 338-9'/%3E%3Cpath d='M119 98C138 87 143 74 159 68C177 61 190 67 205 60C222 52 226 36 244 28C263 20 279 28 295 23C311 18 322 9 335-2'/%3E%3Cpath d='M140 98C154 88 158 79 171 74C185 68 197 73 209 67C224 60 228 46 243 39C259 31 272 38 287 34C302 30 314 21 328 10'/%3E%3Cpath d='M163 98C174 89 177 84 187 80C198 75 207 79 216 74C228 68 232 57 244 51C257 44 268 50 280 47C293 44 304 36 318 25'/%3E%3C/g%3E%3C/svg%3E");
    --ef-hatch: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.018) 0 1px, transparent 1px 6px);
    --ef-font-display: "HarmonyOS Sans SC", "Noto Sans SC", "Microsoft YaHei UI", sans-serif;
    --ef-font-body: "Noto Sans SC", "HarmonyOS Sans SC", "Microsoft YaHei UI", sans-serif;
    --ef-font-number: Haettenschweiler, "Arial Narrow", "Roboto Condensed", sans-serif;
    --ef-fast: 140ms;
    --ef-shift: 190ms;
}

body {
    background-color: var(--ef-workbench) !important;
    background-image: var(--ef-gray-grid) !important;
    background-size: 160px 160px !important;
    background-position: 0 0 !important;
    background-repeat: repeat !important;
    background-attachment: fixed !important;
    --SmartThemeBodyColor: #eef0ed !important;
    --SmartThemeEmColor: #b9bfbd !important;
    --SmartThemeUnderlineColor: var(--ef-signal) !important;
    --SmartThemeQuoteColor: var(--ef-signal) !important;
    --SmartThemeBlurTintColor: rgba(16, 20, 21, 0.94) !important;
    --SmartThemeChatTintColor: var(--ef-paper) !important;
    --SmartThemeUserMesBlurTintColor: transparent !important;
    --SmartThemeBotMesBlurTintColor: transparent !important;
    --SmartThemeBorderColor: rgba(238, 240, 237, 0.2) !important;
    --SmartThemeShadowColor: transparent !important;
    font-family: var(--ef-font-body) !important;
}

/* 02-foundation.css */
/* A bounded reading plane: the page is the signature, not a synthetic HUD. */
#top-bar,
#top-settings-holder,
#sheld {
    width: min(var(--sheldWidth), 1080px) !important;
    max-width: 1080px !important;
}

/* 宿主在窄窗口把图标条改为 fixed；半宽页面仍须与背景条共同居中。 */
#top-settings-holder {
    inset-inline: 0;
    margin-inline: auto !important;
}

#chat {
    isolation: isolate;
    box-sizing: border-box;
    padding-left: 9px !important;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-body) !important;
    text-shadow: none !important;
    background-color: var(--ef-paper) !important;
    background-image: var(--ef-paper-grid) !important;
    border: 0 !important;
    border-left: 1px solid rgba(23, 26, 26, 0.24) !important;
    border-right: 1px solid rgba(23, 26, 26, 0.24) !important;
    border-radius: 0 !important;
    box-shadow: inset 8px 0 0 var(--ef-signal) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#chat a {
    color: #415d5a !important;
    text-decoration-color: rgba(65, 93, 90, 0.48) !important;
    text-underline-offset: 0.18em;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 0.75em 0 !important;
    padding: 0.55em 0.8em !important;
    color: #343b39 !important;
    background: rgba(23, 26, 26, 0.045) !important;
    border: 0 !important;
    border-left: 3px solid var(--ef-signal) !important;
    border-radius: 0 !important;
}

#chat :is(.mes_text, .mes_reasoning) :is(code, pre) {
    color: var(--ef-ink) !important;
    background: rgba(23, 26, 26, 0.06) !important;
    border-color: rgba(23, 26, 26, 0.16) !important;
    border-radius: 0 !important;
    text-shadow: none !important;
}

@media (max-width: 700px) {
    #top-bar,
    #top-settings-holder,
    #sheld {
        width: 100% !important;
        max-width: none !important;
    }

    #chat {
        padding-left: 6px !important;
        border-inline: 0 !important;
        box-shadow: inset 5px 0 0 var(--ef-signal) !important;
    }
}

/* 03-chat.css */
/* Keep SillyTavern's native flex message skeleton and restyle its real nodes. */
#chat > .mes {
    box-sizing: border-box;
    /* #chat is a fixed-height flex column: without this, messages shrink to
       min-height and their text spills over the following message. */
    flex-shrink: 0;
    min-height: 104px;
    margin: 0 !important;
    padding: 18px 22px 18px 18px !important;
    color: var(--ef-ink) !important;
    background: transparent !important;
    border: 0 !important;
    border-bottom: 1px solid var(--ef-line) !important;
    box-shadow: none !important;
    text-shadow: none !important;
    transition: background-color var(--ef-fast) ease-out;
}

#chat > .mes:hover,
#chat > .mes:focus-within {
    background-color: rgba(255, 255, 255, 0.34) !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex: 0 0 88px;
    flex-direction: column;
    align-items: flex-start;
    min-width: 0;
    padding: 0 20px 0 0 !important;
    color: var(--ef-muted) !important;
    border-right: 1px solid var(--ef-line) !important;
}

#chat > .last_mes:not(.smallSysMes) > .mesAvatarWrapper {
    padding-bottom: 0 !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper::after {
    content: "";
    width: 18px;
    height: 3px;
    margin-top: 10px;
    background: var(--ef-signal);
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar,
#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
    box-sizing: border-box;
    width: 50px !important;
    height: 50px !important;
    min-width: 50px;
    min-height: 50px;
    border-radius: 0 !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar {
    flex: 0 0 50px !important;
    filter: grayscale(0.2) contrast(1.04);
    background: var(--ef-graphite) !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
    object-fit: cover;
    border: 1px solid rgba(23, 26, 26, 0.32) !important;
    box-shadow: none !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    max-width: 66px;
    margin: 5px 0 0 !important;
    color: var(--ef-muted) !important;
    font: 600 10px/1.25 var(--ef-font-number) !important;
    letter-spacing: 0.035em;
    text-align: left !important;
    text-shadow: none !important;
}

#chat > .mes:not(.smallSysMes) > .mes_block {
    position: relative;
    box-sizing: border-box;
    flex: 1 1 auto;
    min-width: 0;
    padding: 0 0 0 20px !important;
    overflow-x: hidden;
    color: var(--ef-ink) !important;
}

#chat > .mes .ch_name {
    position: relative;
    min-height: 26px;
    padding: 0 0 8px !important;
    color: var(--ef-ink) !important;
    border-bottom: 1px solid var(--ef-line-soft);
}

#chat > .mes .ch_name .name_text {
    position: relative;
    z-index: 1;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-display) !important;
    font-size: 1.12em;
    font-weight: 800 !important;
    letter-spacing: 0.025em;
}

#chat > .mes[is_user="false"]:not([is_system="true"]) .ch_name .name_text {
    display: inline-block;
    padding: 2px 7px 2px 6px;
    color: var(--ef-ink) !important;
    background: var(--ef-signal);
}

#chat > .mes[is_user="false"]:not([is_system="true"]) .ch_name .name_text::before {
    content: "[";
}

#chat > .mes[is_user="false"]:not([is_system="true"]) .ch_name .name_text::after {
    content: "]";
}

/* 时间戳含"年月日"，条件字体没有 CJK 字形会宽窄混杂，改用正文字体等宽数字。 */
#chat > .mes .timestamp {
    margin-left: 8px;
    color: var(--ef-muted) !important;
    font: 500 10px/1 var(--ef-font-body) !important;
    font-variant-numeric: tabular-nums !important;
    letter-spacing: 0.02em;
    text-shadow: none !important;
}

/* 官方长图正文基线距 42px／字高 26px = 1.6；原 1.75 偏松，压紧后层级更清楚。 */
#chat > .mes .mes_text {
    padding: 12px var(--mes-right-spacing) 4px 0 !important;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-body) !important;
    font-weight: 470 !important;
    line-height: 1.6 !important;
}

#chat > .mes[is_user="false"] .mes_text :is(em, i) {
    color: #4f5754 !important;
}

#chat > .mes[is_user="false"] .mes_text q {
    color: #303735 !important;
    font-weight: 650 !important;
}

#chat > .mes .mes_buttons,
#chat > .mes .extraMesButtons,
#chat > .mes .mes_edit_buttons,
#chat > .mes .mes_reasoning_actions {
    color: var(--ef-ink) !important;
    text-shadow: none !important;
}

#chat > .mes :is(.mes_button, .extraMesButtons > div) {
    color: inherit !important;
    filter: none !important;
}

#chat > .mes .mes_reasoning_details {
    margin-top: 9px;
    color: #4e5653 !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
}

#chat > .mes .mes_reasoning_summary,
#chat > .mes .mes_reasoning {
    color: inherit !important;
    text-shadow: none !important;
}

#chat > .mes :is(.edit_textarea, .reasoning_edit_textarea) {
    color: var(--ef-ink) !important;
    caret-color: var(--ef-ink) !important;
    background: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid rgba(23, 26, 26, 0.26) !important;
    border-radius: 0 !important;
    box-shadow: inset 3px 0 var(--ef-signal) !important;
}

#chat > .mes .mes_media_wrapper,
#chat > .mes .mes_file_wrapper {
    color: var(--ef-ink) !important;
}

/* User turns become local graphite evidence blocks, never full-width dark cards. */
#chat > .mes[is_user="true"] {
    background: rgba(23, 26, 26, 0.025) !important;
}

#chat > .mes[is_user="true"] > .mes_block {
    margin: 0 0 0 12px;
    padding: 14px 16px 14px 20px !important;
    color: var(--ef-paper-hi) !important;
    background-color: var(--ef-graphite) !important;
    background-image: var(--ef-hatch) !important;
    box-shadow: inset 4px 0 0 var(--ef-signal) !important;
}

#chat > .mes[is_user="true"] > .mes_block .ch_name {
    color: var(--ef-paper-hi) !important;
    border-bottom-color: rgba(255, 255, 255, 0.12);
}

#chat > .mes[is_user="true"] > .mes_block :is(.name_text, .mes_text, .mes_reasoning_summary, .mes_reasoning) {
    color: var(--ef-paper-hi) !important;
}

#chat > .mes[is_user="true"] > .mes_block .mes_text :is(em, i) {
    color: rgba(250, 251, 248, 0.76) !important;
}

#chat > .mes[is_user="true"] > .mes_block .mes_text q {
    color: var(--ef-signal) !important;
}

#chat > .mes[is_user="true"] > .mes_block .timestamp {
    color: rgba(250, 251, 248, 0.52) !important;
}

#chat > .mes[is_user="true"] > .mes_block :is(.mes_buttons, .extraMesButtons, .mes_edit_buttons, .mes_reasoning_actions) {
    color: var(--ef-paper-hi) !important;
}

#chat > .mes[is_user="true"] > .mes_block a {
    color: var(--ef-signal) !important;
    text-decoration-color: rgba(236, 242, 0, 0.48) !important;
}

#chat > .mes[is_user="true"] > .mes_block :is(.mes_text, .mes_reasoning) blockquote {
    color: rgba(250, 251, 248, 0.82) !important;
    background: rgba(255, 255, 255, 0.055) !important;
}

#chat > .mes[is_user="true"] > .mes_block :is(.mes_text, .mes_reasoning) :is(code, pre) {
    color: var(--ef-paper-hi) !important;
    background: rgba(0, 0, 0, 0.22) !important;
    border-color: rgba(255, 255, 255, 0.16) !important;
}

#chat > .mes[is_user="true"] > .mes_block .mes_reasoning_details {
    color: rgba(250, 251, 248, 0.75) !important;
    background: transparent !important;
    border: 0 !important;
}

#chat > .mes[is_user="true"] > .mes_block :is(.edit_textarea, .reasoning_edit_textarea) {
    color: var(--ef-paper-hi) !important;
    caret-color: var(--ef-signal) !important;
    background: rgba(0, 0, 0, 0.2) !important;
    border-color: rgba(255, 255, 255, 0.22) !important;
}

#chat > .mes.smallSysMes {
    padding: 8px 18px !important;
    color: #555d5a !important;
    background-color: var(--ef-workbench) !important;
    background-image: var(--ef-gray-grid) !important;
    background-size: 160px 160px !important;
    background-position: 0 0 !important;
    background-repeat: repeat !important;
}

#chat > .mes.smallSysMes > .mes_block {
    color: inherit !important;
}

#chat > .mes.smallSysMes .mes_text {
    padding: 4px 0 !important;
    color: inherit !important;
    line-height: 1.45 !important;
}

#chat > .mes.selected {
    background-color: rgba(236, 242, 0, 0.22) !important;
}

#chat > .mes :is(.swipe_left, .swipe_right, .swipes-counter) {
    color: var(--ef-ink) !important;
    text-shadow: none !important;
}

#chat > .mes[is_user="true"] :is(.swipe_right, .swipes-counter) {
    color: var(--ef-paper-hi) !important;
}

/* Optional extension control: retain the action while preventing a foreign round badge. */
#chat .xiaobaix-collapse-btn {
    box-sizing: border-box !important;
    width: 24px !important;
    height: 24px !important;
    color: var(--ef-ink) !important;
    background: transparent !important;
    border: 1px solid var(--ef-line) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

#chat .xiaobaix-collapse-btn .xiaobaix-xstack {
    transform: scale(0.66);
}

#chat > .mes[is_user="true"] .xiaobaix-collapse-btn {
    color: var(--ef-paper-hi) !important;
    border-color: rgba(255, 255, 255, 0.18) !important;
}

@media (max-width: 700px) {
    #chat > .mes {
        padding: 13px 12px 14px 11px !important;
    }

    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper {
        flex-basis: 58px;
        padding-right: 12px !important;
    }

    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar,
    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
        width: 38px !important;
        height: 38px !important;
        min-width: 38px;
        min-height: 38px;
    }

    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar {
        flex-basis: 38px !important;
    }

    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper::after {
        width: 13px;
        margin-top: 7px;
    }

    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
        max-width: 44px;
        font-size: 8px !important;
    }

    #chat > .mes:not(.smallSysMes) > .mes_block {
        padding-left: 12px !important;
    }

    #chat > .mes[is_user="true"] > .mes_block {
        margin-left: 4px;
        padding: 11px 10px 11px 14px !important;
    }

    #chat > .mes .mes_text {
        padding-top: 9px !important;
        line-height: 1.65 !important;
    }

    #chat > .mes .ch_name .name_text {
        font-size: 0.86em;
    }
}

/* 04-input.css */
/* Accepted input-review: fine shell, focus line and textured paper-plane button. */
#form_sheld {
    --ef-input-ink: #242424;
    --ef-input-paper: #eeeded;
    --ef-input-paper-hi: #faf9f9;
    --ef-input-signal: #fffa00;
    --ef-input-font: "EF Cover Harmony Regular", "HarmonyOS Sans SC", "Microsoft YaHei UI", sans-serif;
    position: relative;
    box-sizing: border-box;
    container: ef-input / inline-size;
    flex-shrink: 0;
    width: 100%;
    margin-top: 0 !important;
    padding: 0;
    white-space: normal;
    color: var(--ef-input-ink);
    background: var(--ef-input-paper);
    border: 1px solid #a8a5a5;
    border-radius: 5px;
    box-shadow: 0 2px 5px #0000001a, 0 0 0 1px #ffffff70;
    isolation: isolate;
}

body.no-blur #send_form,
body:not(.no-blur) #send_form {
    --bottomFormBlockSize: 34px;
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-wrap: wrap;
    width: 100%;
    margin: 0;
    color: var(--ef-input-ink);
    background: var(--ef-input-paper-hi) !important;
    border: 0;
    border-top: 1px solid #fff;
    border-radius: 4px;
    box-shadow: inset 0 0 0 1px #fff;
    clip-path: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

#send_form::before {
    content: "";
    position: absolute;
    z-index: 4;
    top: 0;
    left: 3px;
    width: 104px;
    height: 3px;
    pointer-events: none;
    background: var(--ef-input-signal);
    transform: scaleX(.24);
    transform-origin: left;
    transition: transform 190ms ease-out;
}

#form_sheld:focus-within { border-color: #8c8888; }
#send_form:focus-within,
#send_form:has(#send_textarea:focus-visible) { outline: none; border-top-color: #fff; }
#send_form:focus-within::before { transform: scaleX(1); }

#nonQRFormItems {
    --ef-input-columns: auto minmax(0, 1fr) auto;
    --ef-input-text-column: 2;
    --ef-input-tool-row: 1;
    --ef-input-right-column: 3;
    --ef-input-tool-border: 1px solid #d6d4d4;
    --ef-input-right-wrap: nowrap;
    order: 25;
    display: grid;
    grid-template-columns: var(--ef-input-columns);
    align-items: end;
    gap: 5px;
    width: 100%;
    min-width: 0;
    padding: 4px 5px;
    color: var(--ef-input-ink);
    background: transparent;
}

#leftSendForm,
#rightSendForm {
    display: flex;
    align-items: center;
    align-self: end;
    grid-row: var(--ef-input-tool-row);
    gap: 2px;
    width: auto;
    min-width: 0;
    min-height: 34px;
    padding: 0;
}

#send_form #leftSendForm {
    grid-column: 1;
    justify-self: start;
    flex-wrap: nowrap;
    padding-right: 3px;
    border-right: var(--ef-input-tool-border);
}

#send_form #rightSendForm {
    grid-column: var(--ef-input-right-column);
    justify-self: end;
    justify-content: flex-end;
    flex-wrap: var(--ef-input-right-wrap);
    max-width: 100%;
}

/* The host owns display for generation, scripts and extension toggles. */
#leftSendForm > div,
#rightSendForm > div:not(.mes_stop),
#rightSendForm > .mes_stop {
    position: relative;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    width: 30px;
    height: 34px;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 2px;
    color: #5a5858;
    background: transparent;
    font-size: 16px;
    cursor: pointer;
    opacity: 1;
    filter: none;
    text-shadow: none;
    outline-offset: -2px;
    transition: background-color 100ms linear, color 100ms linear;
}

#leftSendForm > div:hover,
#leftSendForm > div:focus-visible,
#rightSendForm > div:not(#send_but):hover,
#rightSendForm > div:not(#send_but):focus-visible {
    color: #252424;
    background: #dedbdb;
    filter: none;
    outline: 1px solid #bab7b7;
    outline-offset: -2px;
}

#leftSendForm > div[aria-expanded="true"] {
