}

#send_textarea {
    grid-column: var(--ef-input-text-column);
    grid-row: 1;
    display: block;
    width: 100%;
    min-width: 0;
    min-height: 34px;
    height: auto;
    max-height: 50vh;
    max-height: 50dvh;
    margin: 0;
    padding: 6px 6px 4px;
    resize: vertical;
    field-sizing: content;
    overflow: auto;
    color: var(--ef-input-ink);
    background: transparent;
    font: 400 14px/21px var(--ef-input-font);
    letter-spacing: 0;
    text-align: left;
    box-shadow: none;
    text-shadow: none;
    caret-color: var(--ef-input-ink);
    scrollbar-color: auto;
    scrollbar-width: auto;
    --progColor: #91a7bd;
    --progFlashColor: #b29582;
    --progSuccessColor: #789771;
    --progErrorColor: #b65c59;
