        url("data:image/png;base64,") right center / 107px 24px no-repeat,
        var(--button-fill);
    box-shadow: inset 0 0 0 2px var(--button-fill), inset 0 0 0 3px var(--button-rim), 0 2px 3px #00000026;
    font-size: 15px;
    transition: background-color 100ms linear, color 100ms linear;
}

#send_but::before {
    position: absolute;
    right: 6px;
    top: 50%;
    transform: translateY(-50%);
