/* 05-motion.css */
/* Only the newest real message receives a short print-registration sweep. */
#chat > .last_mes:not(.smallSysMes) > .mes_block::after {
    content: "";
    position: absolute;
    z-index: 2;
    top: 0;
    left: 20px;
    width: min(210px, 46%);
    height: 3px;
    pointer-events: none;
    background-color: var(--ef-signal);
    background-image: var(--ef-contours);
    transform-origin: left;
}

/* 推理：只做诚实的展开淡入。思考态真信号酒馆没给 DOM，
   不做 last_mes 冒充的假加载（2026-09-04 决议）。 */

@media (prefers-reduced-motion: no-preference) {
    #chat > .last_mes:not(.smallSysMes) > .mes_block::after {
        animation: ef-registration-sweep 260ms cubic-bezier(0.2, 0.75, 0.2, 1) both;
    }

    #top-settings-holder > .drawer > .drawer-content.openDrawer {
        animation: ef-menu-resolve var(--ef-shift) cubic-bezier(0.2, 0.72, 0.2, 1) both;
    }

    /* 推理展开：正文短淡入，每次打开都播一次。 */
    #chat > .mes .mes_reasoning_details[open] > .mes_reasoning {
        animation: ef-reasoning-expand 190ms cubic-bezier(0.2, 0.72, 0.2, 1) both;
    }
}

@keyframes ef-registration-sweep {
    from {
        opacity: 0;
        transform: scaleX(0.08);
    }

    to {
        opacity: 1;
        transform: scaleX(1);
    }
}

/* Official menu-category changes resolve from a short blank/dim interval. */
@keyframes ef-menu-resolve {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

/* 推理展开：短淡入 + 3px 上浮归位。 */
@keyframes ef-reasoning-expand {
    from {
        opacity: 0;
        transform: translateY(-3px);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

body.reduced-motion #top-settings-holder > .drawer > .drawer-content {
    animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
    #chat > .mes,
    #send_form,
    #send_form::before,
    #send_but,
    #top-settings-holder > .drawer > .drawer-toggle,
    #top-settings-holder > .drawer > .drawer-toggle::after {
        scroll-behavior: auto !important;
        animation: none !important;
        transition: none !important;
    }

    #chat > .last_mes:not(.smallSysMes) > .mes_block::after,
    #send_form::before {
        transform: scaleX(1) !important;
    }
}

/* 06-controls.css */
/* Functional controls: neutral tools, yellow only for selected navigation and primary action. */

#chat .menu_button {
    color: var(--ef-ink) !important;
    background: rgba(250, 251, 248, 0.48) !important;
    border: 1px solid rgba(23, 26, 26, 0.2) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
    transition:
        color var(--ef-fast) ease-out,
        background-color var(--ef-fast) ease-out,
        border-color var(--ef-fast) ease-out;
}

#chat .menu_button :is(.fa-solid, .fa-regular, .fa-brands) {
