    opacity: 1 !important;
}

#chat .menu_button:hover {
    color: var(--ef-ink) !important;
    background: rgba(23, 26, 26, 0.065) !important;
    border-color: rgba(23, 26, 26, 0.34) !important;
}

/* 激活态用黄色标记而非整块实心填充：SPEC 把黄色留给左轨、章节条、聚焦线和发送按钮，
   次要图标按钮铺满黄底会稀释掉主强调。 */
#chat .menu_button.active {
    color: var(--ef-ink) !important;
    background: rgba(236, 242, 0, 0.22) !important;
    border-color: rgba(23, 26, 26, 0.28) !important;
