    outline-offset: 1px;
}

#chat .mes_button {
    border-radius: 0 !important;
    filter: none !important;
    text-shadow: none !important;
    transition:
        color var(--ef-fast) ease-out,
        background-color var(--ef-fast) ease-out,
        opacity var(--ef-fast) ease-out;
}

#chat .mes_button:hover {
    color: var(--ef-ink) !important;
    background-color: rgba(23, 26, 26, 0.065) !important;
    opacity: 1 !important;
}

#chat > .mes[is_user="true"] .menu_button {
    color: var(--ef-paper-hi) !important;
    background: rgba(255, 255, 255, 0.035) !important;
