}

@media (prefers-reduced-motion: reduce) {
    #top-settings-holder > .drawer > .drawer-toggle > .drawer-icon,
    #chat .menu_button,
    #chat .mes_button,
    #leftSendForm > div,
    #rightSendForm > div:not(#send_but),
