/* 07-user-settings.css */
/* User Settings sample: dark title shell, continuous light work surface, sparse signal yellow. */

#user-settings-button > #user-settings-block {
    --ef-settings-field: rgba(23, 26, 26, 0.045);
    --ef-settings-soft: var(--ef-workbench);
    --ef-settings-rule: rgba(23, 26, 26, 0.18);
    --ef-settings-rule-strong: rgba(23, 26, 26, 0.22);
    container-name: ef-user-settings;
    container-type: inline-size;
    box-sizing: border-box;
    width: 100% !important;
    max-width: 1080px !important;
    margin: 0 auto !important;
    padding: 0 !important;
    color: var(--ef-paper-hi) !important;
    background: var(--ef-void-soft) !important;
    border: 1px solid rgba(238, 240, 237, 0.18) !important;
    border-top: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    transition-duration: var(--ef-shift) !important;
}

#user-settings-button > #user-settings-block > .flex-container.flexFlowColumn:first-child {
    position: sticky;
    z-index: 4;
    top: 0;
    gap: 6px !important;
    padding: 7px 10px 8px 13px;
    background: var(--ef-void) !important;
    border-bottom: 2px solid var(--ef-signal);
    box-shadow: none;
}

#user-settings-button #user-settings-block [name="userSettingsRowOne"],
#user-settings-button #user-settings-block [name="UserSettingsRowTwo"] {
    gap: 8px !important;
}

#user-settings-button #user-settings-block h3 {
    display: flex;
    align-items: center;
    gap: 6px;
    color: var(--ef-paper-hi) !important;
    font-family: var(--ef-font-display) !important;
    font-size: calc(var(--mainFontSize) * 1.08) !important;
    font-weight: 700 !important;
    line-height: 1.2;
    letter-spacing: 0.005em;
    text-shadow: none !important;
}

#user-settings-button #user-settings-block h3::before {
    content: "//";
    width: auto;
    height: auto;
    flex: 0 0 auto;
    color: rgba(238, 240, 237, 0.82);
    background: transparent;
    box-shadow: none;
    font-family: Bahnschrift, "Arial Narrow", sans-serif;
    font-size: 0.86em;
    font-weight: 700;
    letter-spacing: -0.08em;
}

#user-settings-button #user-settings-block h3 > span:first-child::before {
    content: "";
    margin-right: 0.08em;
}

#user-settings-button #user-settings-block h3 > span:first-child::after {
    content: "";
    margin-left: 0.08em;
}

#user-settings-button #user-settings-block .notes-link {
    color: rgba(238, 240, 237, 0.5) !important;
}

#user-settings-button #user-settings-block .notes-link:hover,
#user-settings-button #user-settings-block .notes-link:focus-visible {
    color: var(--ef-signal) !important;
}

#user-settings-button #UI-language-block {
    gap: 7px !important;
    color: rgba(238, 240, 237, 0.72) !important;
    font-size: calc(var(--mainFontSize) * 0.86);
}

#user-settings-button #ui_language_select {
    min-height: 29px;
    margin: 0 !important;
    color: var(--ef-paper-hi) !important;
    background-color: rgba(255, 255, 255, 0.045) !important;
    border: 0 !important;
    border-bottom: 1px solid rgba(238, 240, 237, 0.22) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
}

#user-settings-button #version_display {
    color: rgba(238, 240, 237, 0.48) !important;
    font-family: var(--ef-font-number) !important;
    font-size: calc(var(--mainFontSize) * 0.82) !important;
    letter-spacing: 0.04em;
    text-shadow: none !important;
}

#user-settings-button #settingsSearch {
    min-height: 30px;
    height: 30px;
    margin: 0 !important;
    padding: 5px 9px !important;
    resize: none;
    color: var(--ef-paper-hi) !important;
    background: rgba(255, 255, 255, 0.04) !important;
    border: 0 !important;
    border-bottom: 1px solid rgba(238, 240, 237, 0.22) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    transition: border-color var(--ef-fast) ease-out, box-shadow var(--ef-fast) ease-out;
}

#user-settings-button #settingsSearch::placeholder {
    color: rgba(238, 240, 237, 0.42) !important;
}

#user-settings-button #settingsSearch:focus-visible,
#user-settings-button #ui_language_select:focus-visible {
    border-color: var(--ef-signal) !important;
    outline: 1px solid var(--ef-signal) !important;
    outline-offset: 1px;
    box-shadow: inset 2px 0 0 var(--ef-signal) !important;
}

#user-settings-button #account_button {
    min-height: 30px;
    margin: 0 !important;
    padding: 4px 10px !important;
    gap: 6px !important;
    color: var(--ef-paper-hi) !important;
    background: rgba(255, 255, 255, 0.065) !important;
    border: 1px solid transparent !important;
    border-radius: 999px !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
}

#user-settings-button #account_button:hover,
#user-settings-button #account_button:focus-visible {
    color: var(--ef-paper-hi) !important;
    background: rgba(255, 255, 255, 0.08) !important;
    border-color: transparent !important;
}

#user-settings-button #account_button:focus-visible {
    outline: 2px solid var(--ef-signal) !important;
    outline-offset: 1px;
}

#user-settings-button #user-settings-block-content {
    align-items: flex-start;
    gap: 0 !important;
    box-sizing: border-box;
    padding: 11px 10px 24px !important;
    color: var(--ef-ink) !important;
    background-color: var(--ef-paper) !important;
    background-image: var(--ef-paper-grid) !important;
    text-shadow: none !important;
}

#user-settings-button #user-settings-block-content > :is(
    #UI-Theme-Block,
    #UI-Customization,
    #power-user-options-block
) {
    box-sizing: border-box;
    min-width: 0;
    padding-inline: 11px;
    color: var(--ef-ink) !important;
}

#user-settings-button #user-settings-block-content > #UI-Customization {
    border-inline: 1px solid var(--ef-settings-rule);
}

#user-settings-button #user-settings-block-content :is(label, small, span, b) {
    color: inherit !important;
    text-shadow: none !important;
}

#user-settings-button #user-settings-block-content hr {
    height: 1px;
    margin: 9px 0 !important;
    background: var(--ef-settings-rule) !important;
    border: 0 !important;
}

#user-settings-button #user-settings-block h4 {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: flex-start !important;
    gap: 7px;
    min-height: 32px;
    margin: 0 0 10px !important;
    padding: 5px 8px 5px 0 !important;
    color: var(--ef-ink) !important;
    background: transparent !important;
    border: 0 !important;
    border-bottom: 1px solid var(--ef-settings-rule) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    font-family: var(--ef-font-display) !important;
    font-size: calc(var(--mainFontSize) * 0.96) !important;
    font-weight: 700 !important;
    line-height: 1.2;
    letter-spacing: 0.005em;
    text-align: left !important;
    text-shadow: none !important;
}

#user-settings-button #user-settings-block h4::before {
    content: "";
    flex: 0 0 2px;
    width: 2px;
    height: 14px;
    background: var(--ef-signal);
}

#user-settings-button #user-settings-block h4 > .flex-container {
    margin-left: auto !important;
}

/* 50% 页面宽度下三枚主题操作按钮需要独占下一行，避免把“UI 主题”挤成竖排。 */
#user-settings-button #UI-presets-block h4.title_restorable {
    flex-wrap: wrap;
}

#user-settings-button #UI-presets-block h4.title_restorable > span:first-child {
    white-space: nowrap;
}

#user-settings-button #user-settings-block .inline-drawer-toggle.userSettingsInnerExpandable {
    min-height: 30px;
    margin: 3px 0 0 !important;
    padding: 5px 8px !important;
    color: var(--ef-ink) !important;
    background: rgba(23, 26, 26, 0.045) !important;
    border: 0 !important;
    border-left: 2px solid transparent !important;
    border-bottom: 1px solid var(--ef-settings-rule) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    transition:
        color var(--ef-fast) ease-out,
        background-color var(--ef-fast) ease-out,
        border-color var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block .inline-drawer-toggle.userSettingsInnerExpandable:hover {
    background: rgba(23, 26, 26, 0.085) !important;
}

#user-settings-button #user-settings-block .inline-drawer-toggle.userSettingsInnerExpandable:has(> .inline-drawer-icon.up) {
    color: var(--ef-ink) !important;
    background: rgba(23, 26, 26, 0.045) !important;
    border-left-color: var(--ef-signal) !important;
}

#user-settings-button #user-settings-block .inline-drawer-icon {
    display: grid !important;
    width: 20px;
    height: 20px;
    place-items: center;
    color: currentColor !important;
    font-size: 0 !important;
    filter: none !important;
}

#user-settings-button #user-settings-block .inline-drawer-icon::before {
    content: "" !important;
    display: block;
    width: 7px;
    height: 7px;
    border-right: 1.5px solid currentColor;
    border-bottom: 1.5px solid currentColor;
    transform: translateY(-2px) rotate(45deg);
    transition: transform var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block .inline-drawer-icon.up::before {
    transform: translateY(2px) rotate(225deg);
}

#user-settings-button #user-settings-block .inline-drawer-content {
    padding: 8px 8px 10px !important;
    color: var(--ef-ink) !important;
    background: rgba(23, 26, 26, 0.018) !important;
    border: 0 !important;
    border-radius: 0 !important;
}

#user-settings-button #user-settings-block-content select {
    box-sizing: border-box;
    min-height: 30px;
    color: var(--ef-ink) !important;
    background-color: var(--ef-settings-field) !important;
    background-image: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 10 8' fill='none' stroke='%23171a1a' stroke-width='1.4' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M1 2l4 4 4-4'/%3E%3C/svg%3E") !important;
    background-position: right 9px center !important;
    background-repeat: no-repeat !important;
    background-size: 10px 8px !important;
    border: 0 !important;
    border-bottom: 1px solid var(--ef-settings-rule-strong) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding-block: 4px !important;
    padding-right: 27px !important;
    text-shadow: none !important;
    transition: border-color var(--ef-fast) ease-out, box-shadow var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block-content select.margin0 {
    margin: 0 !important;
}

#user-settings-button #user-settings-block-content #themes {
    min-width: 0 !important;
    flex: 1 1 0 !important;
}

#user-settings-button #user-settings-block-content select option {
    color: var(--ef-ink);
    background: var(--ef-settings-field);
}

#user-settings-button #user-settings-block-content :is(
    textarea,
    input[type="number"],
    input[type="text"],
    input[type="search"],
    input[type="url"],
    input[type="password"],
    input:not([type])
) {
    box-sizing: border-box;
    min-height: 30px;
    color: var(--ef-ink) !important;
    background: var(--ef-settings-field) !important;
    border: 0 !important;
    border-bottom: 1px solid var(--ef-settings-rule-strong) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 5px 7px !important;
    text-shadow: none !important;
    transition: border-color var(--ef-fast) ease-out, box-shadow var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block-content :is(select, textarea, input[type="number"], input[type="text"], input[type="search"], input[type="url"], input[type="password"], input:not([type])):focus-visible {
    border-bottom-color: var(--ef-signal) !important;
    outline: 1px solid var(--ef-graphite) !important;
    outline-offset: 1px;
    box-shadow: inset 2px 0 0 var(--ef-signal) !important;
}

#user-settings-button #user-settings-block-content :is(textarea, input)::placeholder {
    color: rgba(23, 26, 26, 0.46) !important;
}

#user-settings-button #user-settings-block label.checkbox_label {
    min-height: 21px;
    margin-inline: -4px;
    padding: 2px 4px;
    column-gap: 7px !important;
    align-items: center !important;
    color: var(--ef-ink) !important;
    border-left: 2px solid transparent;
    cursor: pointer;
    transition: background-color var(--ef-fast) ease-out, border-color var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block label.checkbox_label:hover {
    background: rgba(23, 26, 26, 0.055);
}

#user-settings-button #user-settings-block label.checkbox_label:has(> input[type="checkbox"]:focus-visible) {
    background: rgba(23, 26, 26, 0.075);
    border-left-color: var(--ef-signal);
}

#user-settings-button #user-settings-block label.checkbox_label > input[type="checkbox"] {
    display: grid;
    width: 16px;
    height: 16px;
    flex: 0 0 16px;
    place-content: center;
    color: var(--ef-ink) !important;
    background: transparent !important;
    border: 1px solid rgba(23, 26, 26, 0.48) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    transform: none !important;
    transition: background-color var(--ef-fast) ease-out, border-color var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block label.checkbox_label > input[type="checkbox"]::before {
    box-shadow: inset 1em 1em var(--ef-ink) !important;
}

#user-settings-button #user-settings-block label.checkbox_label > input[type="checkbox"]:checked {
    background: var(--ef-signal) !important;
    border-color: var(--ef-ink) !important;
}

#user-settings-button #user-settings-block label.checkbox_label > input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--ef-signal) !important;
    outline-offset: 2px;
}

#user-settings-button #user-settings-block label.checkbox_label > input[type="checkbox"]:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

#user-settings-button #user-settings-block input[type="range"] {
    height: 4px !important;
    background: rgba(23, 26, 26, 0.24) !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    transition: background-color var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block input[type="range"]::-webkit-slider-thumb {
    width: 14px;
    height: 14px;
    background: var(--ef-signal) !important;
    border: 2px solid var(--ef-ink) !important;
    border-radius: 0 !important;
    box-shadow: 0 0 0 2px var(--ef-paper) !important;
}

#user-settings-button #user-settings-block input[type="range"]::-moz-range-thumb {
    width: 12px;
    height: 12px;
    background: var(--ef-signal) !important;
    border: 2px solid var(--ef-ink) !important;
    border-radius: 0 !important;
    box-shadow: 0 0 0 2px var(--ef-paper) !important;
}

#user-settings-button #user-settings-block input[type="range"]:focus-visible {
    outline: 1px solid var(--ef-signal) !important;
    outline-offset: 4px;
}

#user-settings-button #user-settings-block-content .neo-range-input {
    min-height: 27px;
    padding: 4px 6px !important;
    font-family: var(--ef-font-number) !important;
    letter-spacing: 0.035em;
}

#user-settings-button #user-settings-block-content .menu_button {
    min-height: 28px;
    padding: 4px 10px !important;
    color: var(--ef-ink) !important;
    background: var(--ef-settings-field) !important;
    border: 1px solid transparent !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
    white-space: nowrap;
    transition:
        color var(--ef-fast) ease-out,
        background-color var(--ef-fast) ease-out,
        border-color var(--ef-fast) ease-out;
}

#user-settings-button #user-settings-block-content div.menu_button:not(:empty):not(:has(> :is(i, svg):only-child)) {
    min-height: 30px;
    padding-inline: 12px !important;
    border-radius: 999px !important;
    line-height: 1.15;
}

#user-settings-button #user-settings-block-content div.menu_button:empty {
    display: inline-grid !important;
    width: 28px !important;
    min-width: 28px !important;
    height: 28px !important;
    min-height: 28px;
    padding: 0 !important;
    place-items: center;
    border-radius: 0 !important;
}

#user-settings-button #user-settings-block-content .menu_button:not(.disabled):not([disabled]):not([aria-disabled="true"]):hover {
    color: var(--ef-paper-hi) !important;
    background: var(--ef-graphite) !important;
    border-color: transparent !important;
}

#user-settings-button #user-settings-block-content .menu_button:focus-visible {
    outline: 1px solid var(--ef-graphite) !important;
    outline-offset: 1px;
    box-shadow: inset 2px 0 0 var(--ef-signal) !important;
}

#user-settings-button #user-settings-block-content .menu_button:is(.disabled, [disabled], [aria-disabled="true"]) {
    opacity: 0.42 !important;
}

#user-settings-button #UI-presets-block .menu_button {
    width: 28px !important;
    min-width: 28px !important;
    padding: 0 !important;
    border-radius: 0 !important;
}

#user-settings-button :is(
    #account_button,
    #ui_preset_import_button,
    #ui_preset_export_button,
    #ui-preset-delete-button,
    #ui-preset-update-button,
    #ui-preset-save-button
) > i::before {
    font-size: 15px !important;
    line-height: 1 !important;
    vertical-align: middle;
}

body.reduced-motion #user-settings-button #user-settings-block,
body.reduced-motion #user-settings-button #user-settings-block *,
body.reduced-motion #user-settings-button #user-settings-block *::before,
body.reduced-motion #user-settings-button #user-settings-block *::after {
    animation: none !important;
    scroll-behavior: auto !important;
    transition: none !important;
}

@media (max-width: 1000px) {
    #user-settings-button > #user-settings-block {
        max-width: none !important;
    }

    #user-settings-button > #user-settings-block > .flex-container.flexFlowColumn:first-child {
        position: relative;
        top: auto;
        padding: 6px 7px 7px 9px;
    }

    #user-settings-button #user-settings-block [name="userSettingsRowOne"] {
        flex-wrap: wrap;
    }

    #user-settings-button #user-settings-block-content {
        padding: 9px 5px 24px !important;
    }

    #user-settings-button #user-settings-block-content > :is(
        #UI-Theme-Block,
        #UI-Customization,
        #power-user-options-block
    ) {
        padding: 0 4px 14px;
        border-inline: 0 !important;
    }

    #user-settings-button #user-settings-block-content > :is(#UI-Customization, #power-user-options-block) {
        padding-top: 12px;
        border-top: 1px solid var(--ef-settings-rule);
    }
}

/* 页面宽度可由酒馆设置为 50%；布局必须响应抽屉本身，而不是只看视口。 */
@container ef-user-settings (max-width: 740px) {
    #user-settings-button #user-settings-block-content {
        flex-direction: column !important;
        flex-wrap: nowrap !important;
        align-items: stretch !important;
        gap: 0 !important;
        padding-inline: 7px !important;
    }

    #user-settings-button #user-settings-block-content > :is(
        #UI-Theme-Block,
        #UI-Customization,
        #power-user-options-block
    ) {
        flex: 0 0 auto !important;
        width: 100% !important;
        max-width: none !important;
        padding: 0 7px 18px !important;
        border-inline: 0 !important;
    }

    #user-settings-button #user-settings-block-content > :is(#UI-Customization, #power-user-options-block) {
        padding-top: 14px !important;
        border-top: 1px solid var(--ef-settings-rule) !important;
    }
}

@container ef-user-settings (min-width: 741px) and (max-width: 980px) {
    #user-settings-button #user-settings-block-content {
        flex-flow: row wrap !important;
        align-items: flex-start !important;
    }

    #user-settings-button #user-settings-block-content > :is(#UI-Theme-Block, #UI-Customization) {
        flex: 1 1 50% !important;
        width: auto !important;
    }

    #user-settings-button #user-settings-block-content > #UI-Customization {
        border-right: 0 !important;
    }

    #user-settings-button #user-settings-block-content > #power-user-options-block {
        flex: 1 1 100% !important;
        width: 100% !important;
        margin-top: 14px;
        padding-top: 14px !important;
        border-top: 1px solid var(--ef-settings-rule) !important;
    }
}

@media (prefers-reduced-motion: reduce) {
    #user-settings-button #user-settings-block,
    #user-settings-button #user-settings-block *,
    #user-settings-button #user-settings-block *::before,
    #user-settings-button #user-settings-block *::after {
        animation: none !important;
        scroll-behavior: auto !important;
        transition: none !important;
    }
}

/* 08-flat-structure.css */
/*
 * Flat structural pass: one shared content axis, continuous list rows and
 * grey section fields. Depth comes from area contrast and rules, never drop shadows.
 */

#chat > .welcomePanel,
#chat > .welcomePanel .welcomeHeader {
    background: transparent !important;
    box-shadow: none !important;
}

/* 宿主 logo 是品红位图，在黑白黄体系里是唯一的第四种色相；压成墨色单色。 */
#chat > .welcomePanel .welcomeHeaderLogo {
    filter: grayscale(1) contrast(1.2) brightness(0.32) !important;
}

#chat > .welcomePanel .welcomeHeaderTitle {
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-display) !important;
    font-weight: 800 !important;
    letter-spacing: 0.01em;
    text-shadow: none !important;
}

@media (min-width: 701px) {
    #chat > .mes {
        padding: 14px 18px !important;
    }

    #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper {
        flex-basis: 58px;
        padding-right: 7px !important;
    }

    #chat > .mes[is_user="false"]:not([is_system="true"]):not(.smallSysMes) > .mes_block {
        padding-left: 6px !important;
    }

    #chat > .mes .ch_name {
        padding-bottom: 6px !important;
    }

    #chat > .mes .mes_text {
        padding-top: 10px !important;
        line-height: 1.7 !important;
    }
}

body.reduced-motion #chat > .welcomePanel .recentChat {
    transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
    #chat > .welcomePanel .recentChat {
        transition: none !important;
    }
}

/* 09-floor-index.css */
/*
 * 楼层编号：官方长图的两位数分节标记，落在头像左侧的页边槽。
 * 编号取 ST 原生 mesid，和 /go 等命令看到的楼层号一致；个位数补零成两位，
 * 保持长图的编号节奏。单位数值域只有 0–9，所以一条 :is() 即可穷举。
 * padding-top 让编号落到角色名一行的基线附近，而非贴头像顶 —— 官方编号是与
 * 标题成组的，不是浮在角落。
 */

#chat > .mes:not(.smallSysMes)::before {
    content: attr(mesid);
    flex: 0 0 30px;
    padding-top: 15px;
    color: var(--ef-muted);
    font: 400 13px/1 var(--ef-font-number);
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.04em;
    text-align: right;
    -webkit-user-select: none;
    user-select: none;
}

#chat > .mes:not(.smallSysMes):is(
    [mesid="0"], [mesid="1"], [mesid="2"], [mesid="3"], [mesid="4"],
    [mesid="5"], [mesid="6"], [mesid="7"], [mesid="8"], [mesid="9"]
)::before {
    content: "0" attr(mesid);
}

@media (max-width: 700px) {
    #chat > .mes:not(.smallSysMes)::before {
        flex-basis: 20px;
        font-size: 11px;
    }
}

/* 10-section-band.css */
/*
 * 档案章节头：大黄编号 / 矮灰英文签 / 白标题板与右侧黄带。
 * 依据锦陇官方长图局部：英文签贴编号块下沿，白标题板遮住编号下沿。
 * 保留原生标题文字与快捷入口；借父级伪元素放编号，不新增 DOM 或位图文字。
 * 使用主题已内嵌的字体；编号增加露出高度，保留标题压住下沿的关系。
 */

#chat > .welcomePanel {
    counter-reset: ef-section 0;
}

#chat > .welcomePanel .welcomeHeader {
    --ef-section-title-size: 28px;
    --ef-section-title-row: calc(var(--ef-section-title-size) * 1.25);
    --ef-section-meta-row: 32px;
    --ef-section-number-width: 54px;
    --ef-section-number-size: 39px;
    --ef-section-overlap: 5px;
    --ef-section-label-size: 8px;
    position: relative;
    isolation: isolate;
    counter-increment: ef-section;
}

/* 编号在标题下层；以底行定位，右侧快捷入口换行也不会拖散两层。 */
#chat > .welcomePanel .welcomeHeader::before {
    content: counter(ef-section, decimal-leading-zero);
    position: absolute;
    z-index: 0;
    left: 0;
    bottom: calc(var(--ef-section-title-row) - var(--ef-section-overlap));
    box-sizing: border-box;
    width: var(--ef-section-number-width);
    height: calc(var(--ef-section-meta-row) + var(--ef-section-overlap));
    padding: 0 3px 0 0;
    overflow: hidden;
    color: var(--ef-signal);
    background: var(--ef-block);
    font: 400 var(--ef-section-number-size)/.88 "EF Cover Novecento Medium", "Arial Narrow", sans-serif;
    letter-spacing: -0.015em;
    text-align: right;
    text-shadow: none;
    pointer-events: none;
}

#chat > .welcomePanel .recentChatsTitle {
    position: relative;
    z-index: 1;
    display: grid !important;
    grid-template-columns: max-content minmax(0, 1fr);
    grid-template-rows: var(--ef-section-meta-row) var(--ef-section-title-row);
    column-gap: 7px;
    align-items: stretch;
    align-self: flex-end;
    width: 100% !important;
    min-width: 0;
    padding: 0 !important;
    color: #191919 !important;
    /* 仅底行是不透明白板，上行透明，才能露出下层编号。 */
    background: linear-gradient(var(--ef-paper-hi), var(--ef-paper-hi)) left bottom / 100% var(--ef-section-title-row) no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    font-family: "EF Cover Harmony Bold", "Microsoft YaHei", sans-serif !important;
    font-size: var(--ef-section-title-size) !important;
    font-weight: 700 !important;
    letter-spacing: -.025em;
    line-height: 1.25 !important;
    text-shadow: none !important;
}

/* 英文只作低矮附签，不与编号共享字号、基线或字距。 */
#chat > .welcomePanel .recentChatsTitle::before {
    content: "ARKNIGHTS: ENDFIELD";
    grid-row: 1;
    grid-column: 1 / -1;
    justify-self: start;
    align-self: end;
    margin-left: var(--ef-section-number-width);
    padding: 0 4px;
    color: var(--ef-paper-hi);
    background: var(--ef-label);
    font: 700 var(--ef-section-label-size)/1.3 Arial, sans-serif;
    letter-spacing: 0;
    white-space: nowrap;
    pointer-events: none;
}

/* 原生中文文字自动落在第二行第一格，右侧黄带延续到标题区边缘。 */
#chat > .welcomePanel .recentChatsTitle::after {
    content: "";
    grid-row: 2;
    grid-column: 2;
    display: block;
    background: var(--ef-signal);
    pointer-events: none;
}

/* 原生“隐藏最近聊天”状态必须连同新增的编号一起隐藏。 */
#chat > .welcomePanel.recentHidden .recentChatsTitle,
#chat > .welcomePanel.recentHidden .welcomeHeader::before {
    display: none !important;
}

@container ef-welcome (max-width: 520px) {
    #chat > .welcomePanel .welcomeHeader {
        --ef-section-title-size: 24px;
    }
}

/* 11-archive-marks.css */
/*
 * 档案页记号：页眉套准色条与 // 标签前缀。
 *
 * 套准色条实测（2025-12-09-dijiang-update-02.png，画布 1000px，行 y=17–21）：
 *   高 5px；洋红 #d025ce 占 x 61–186，淡黄 #fcf56d 占 190–292，青绿 #34e3ad 占 295–605。
 *   三段不等宽，起于 6.1%、止于 60.5%，右侧留空 —— 是印刷套准标记，不是装饰满铺。
 *   注意这里的淡黄是套准色，不是主强调的 --ef-signal 纯黄，两者不可混用。
 *
 * // 前缀是官方图注的固定记号（形如「// 行迹高塔」），只给真实的子块标签，
 * 不铺到普通正文或按钮上。
 */

#chat > .welcomePanel {
    position: relative;
}

#chat > .welcomePanel::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 5px;
    background: linear-gradient(
        to right,
        transparent 0 6.1%,
        var(--ef-calib-m) 6.1% 18.7%,
        transparent 18.7% 19%,
        var(--ef-calib-y) 19% 29.3%,
        transparent 29.3% 29.5%,
        var(--ef-calib-c) 29.5% 60.5%,
        transparent 60.5%
    );
    pointer-events: none;
}

#chat > .welcomePanel .welcomeHeader {
    padding-top: 13px !important;
}

/*
 * 推理头块：文档式深色当前块（学官网 Button_button / 百科当前条目）。
 * 实测依据：Button_button 142×32、#383838、2px 角、黄竖线 ::after（左 0.5rem、
 * 宽 1rem 裁 25%、高 55%）、texture 全铺 ::before、hover 只动单维度 0.2s。
 * 纹理用主题自有的 --ef-contours-light（白线），不 hotlink 官网图。
 *
 * 真实 DOM：summary > header_block > header > (title + arrow)，另有 actions。
 * thinking/done 的真区分 CSS 拿不到（酒馆 1.18 不写 data-state/body[data-generating]，
 * 纯 JS 变量），用 .last_mes 近似：最新消息=跑，旧消息=静。刚生成完未发下一句
 * 的窗口动画会多跑一会儿，记为 recent-activity，不宣称真思考态。
 */

#chat > .mes .mes_reasoning_summary {
    flex-wrap: wrap !important;
    gap: 0 12px !important;
}

/* 头块底发丝线：静态通栏，不做状态区分。 */
#chat > .mes .mes_reasoning_summary::after {
    content: "" !important;
    flex: none !important;
    order: 99 !important;
    flex-basis: 100% !important;
    height: 1px !important;
    margin-top: 0 !important;
    background: var(--ef-line) !important;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_header_block {
    display: flex !important;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_header {
    position: relative;
    display: inline-flex !important;
    align-items: center !important;
    align-self: flex-start !important;
    gap: 8px !important;
    margin: 0 !important;
    padding: 8px 32px 8px 10px !important;
    border-radius: 2px !important;
    color: var(--ef-paper-hi) !important;
    background: #2b2f2e !important;
}

/* 黄竖线：2px 宽、55% 高，学官网 tick。 */
#chat > .mes .mes_reasoning_summary .mes_reasoning_header::before {
    content: "" !important;
    flex: none !important;
    width: 2px !important;
    height: 18px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: var(--ef-signal) !important;
}

/* 等高线只进深色块右侧，左半渐隐不压字。thinking 态在 05 里复位成色段。 */
#chat > .mes .mes_reasoning_summary .mes_reasoning_header::after {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    width: 55% !important;
    background-image: var(--ef-contours-light) !important;
    background-repeat: no-repeat !important;
    background-position: right center !important;
    background-size: cover !important;
    opacity: 0.5 !important;
    -webkit-mask-image: linear-gradient(to right, transparent 35%, black 75%) !important;
    mask-image: linear-gradient(to right, transparent 35%, black 75%) !important;
    pointer-events: none !important;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_header > * {
    position: relative !important;
    z-index: 1 !important;
}

/* // 注脚：白字降透明，不抢标题。 */
#chat > .mes .mes_reasoning_summary .mes_reasoning_header_title::before {
    content: "// " !important;
    color: rgba(253, 253, 253, 0.6) !important;
    font-style: italic !important;
    font-weight: 600 !important;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_header_title {
    min-width: 0 !important;
    padding: 0 !important;
    overflow-wrap: anywhere !important;
    color: var(--ef-paper-hi) !important;
    font-family: var(--ef-font-display) !important;
    font-size: 14.5px !important;
    font-weight: 700 !important;
    letter-spacing: 0.02em !important;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_arrow {
    color: rgba(253, 253, 253, 0.65) !important;
}

/* 展开收尾：details 折叠时伪元素一起藏，展开才见细线 + 120px 右黑段。
   不做思考/done 区分，纯静态注脚。 */
#chat > .mes:not(.smallSysMes) .mes_reasoning_details::after {
    content: "" !important;
    display: block !important;
    height: 4px !important;
    margin-top: 12px !important;
    background-image:
        linear-gradient(to right, var(--ef-dark) 0 120px, transparent 120px),
        linear-gradient(to right, var(--ef-line) 0 100%) !important;
    background-size:
        120px 4px,
        100% 1px !important;
    background-position:
        100% 100%,
        0 100% !important;
    background-repeat: no-repeat !important;
}

/* 用户消息深底：头块再压深，保证可见。 */
#chat > .mes[is_user="true"] .mes_reasoning_summary .mes_reasoning_header {
    background: rgba(0, 0, 0, 0.45) !important;
}

/*
 * 不给正文的「」和“”加任何装饰。
 * 官方长图里角括号是「标题中引用专有名词」的排版记号，但在聊天正文里它就是对话引号 ——
 * 实测 40 个聊天记录中出现 40,765 次「」与 71,176 次“”，几乎全是台词。
 * 上色或加重会把满屏对白染成装饰，与「装饰降低对比度、正文保持高可读」直接冲突。
 */

/* 12-section-closure.css */
/* 最近聊天已有独立灰底，不再追加无内容的章节收束面板。 */

#chat > .welcomePanel::after {
    content: none !important;
    display: none !important;
}

/* 13-topbar-groups.css */
/* Approved toolbar: continuous dark rail, symmetric texture fade and light open tiles. */
:root {
    /* Native chat/drawer offsets share this token with the visible toolbar. */
    --topBarBlockSize: 44px;
}

#top-bar,
body.no-blur #top-bar {
    box-sizing: border-box;
    height: var(--topBarBlockSize) !important;
    overflow: hidden;
    background: #292929 !important;
    border: 1px solid #454343 !important;
    border-radius: 2px !important;
    box-shadow: 0 1px 3px #00000020 !important;
    backdrop-filter: none !important;
    pointer-events: none;
}

#top-bar::before {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(135deg, #ffffff22 0 1px, transparent 1px 4px);
    mask-image: linear-gradient(90deg, transparent 0%, #000 25% 75%, transparent 100%);
    pointer-events: none;
}

#top-settings-holder {
    --ef-toolbar-glyph: clamp(17px, calc(min(var(--sheldWidth), 1080px) / 21.111), 18px);
    box-sizing: border-box;
    display: grid;
    grid-template-columns: repeat(9, minmax(0, 1fr));
    padding-inline: 1px;
    /* Native drawers must remain free to extend outside the toolbar. */
    overflow: visible;
}

#top-settings-holder > .drawer {
    min-width: 0;
}

#top-settings-holder > .drawer > .drawer-toggle {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: var(--topBarBlockSize);
    color: #d1cdcd !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transition: none;
}

#top-settings-holder > .drawer > .drawer-toggle::before {
    content: "";
    position: absolute;
    inset: 1px;
    border-radius: 2px;
    background: transparent;
    transition: background-color 100ms linear;
    pointer-events: none;
}

#top-settings-holder > .drawer > .drawer-toggle::after {
    content: none;
}

#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon {
    position: relative;
    display: grid;
    place-items: center;
    box-sizing: border-box;
    width: 100%;
    height: var(--topBarBlockSize);
    margin: 0;
    padding: 0;
    color: inherit !important;
    font-size: var(--ef-toolbar-glyph);
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
    opacity: 1 !important;
    transition: color 100ms linear;
}

#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon::before {
    font-size: var(--ef-toolbar-glyph) !important;
    line-height: 1 !important;
}

#top-settings-holder > .drawer > .drawer-toggle:hover,
#top-settings-holder > .drawer > .drawer-toggle:focus-within {
    color: #fffafa !important;
}

#top-settings-holder > .drawer > .drawer-toggle:hover::before,
#top-settings-holder > .drawer > .drawer-toggle:focus-within::before {
    background: #ffffff1a;
}

#top-settings-holder > .drawer > .drawer-toggle:has(> .openIcon) {
    color: #484545 !important;
}

#top-settings-holder > .drawer > .drawer-toggle:has(> .openIcon)::before {
    background: #eeeded;
    box-shadow: inset 0 0 0 1px #cac7c7;
}

#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon:focus-visible {
    outline: 2px solid #f6f2f2 !important;
    outline-offset: -5px;
    border-radius: 3px !important;
}

#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon.openIcon:focus-visible {
    outline-color: #514a4a !important;
}

#top-settings-holder > :is(#WI-SP-button, #extensions-settings-button) > .drawer-toggle > .drawer-icon::after {
    content: "";
    position: absolute;
    left: -1px;
    top: 12px;
    width: 1px;
    height: 20px;
    background: #c3bebe55;
    pointer-events: none;
}

#top-settings-holder > .drawer > .drawer-toggle > #API-status-top.redOverlayGlow {
    color: #efaaa0 !important;
}

#top-settings-holder > .drawer > .drawer-toggle:hover > #API-status-top.redOverlayGlow,
#top-settings-holder > .drawer > .drawer-toggle:focus-within > #API-status-top.redOverlayGlow {
    color: #ffd6d1 !important;
}

#top-settings-holder > .drawer > .drawer-toggle > #API-status-top.redOverlayGlow.openIcon {
    color: #a14b41 !important;
}

@media (max-width: 700px) {
    #top-settings-holder {
        --ef-toolbar-glyph: clamp(17px, calc(100vw / 21.111), 18px);
    }
}

/* The host's iOS branch hard-codes 36px; keep its offsets tied to this toolbar. */
@supports (-webkit-touch-callout: none) {
    #sheld {
        height: calc(100vh - var(--topBarBlockSize) - 1px);
        height: calc(100dvh - var(--topBarBlockSize) - 1px);
        max-height: calc(100dvh - var(--topBarBlockSize) - 1px);
    }

    #top-settings-holder > .drawer > .drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
        top: var(--topBarBlockSize);
        margin-top: 0 !important;
    }

    #top-settings-holder > .drawer > :is(#left-nav-panel, #right-nav-panel) {
        margin-top: 0 !important;
    }
}

body:is(.reduced-motion, .no_animation) #top-settings-holder > .drawer > .drawer-toggle::before,
body:is(.reduced-motion, .no_animation) #top-settings-holder > .drawer > .drawer-toggle > .drawer-icon {
    transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
    #top-settings-holder > .drawer > .drawer-toggle::before,
    #top-settings-holder > .drawer > .drawer-toggle > .drawer-icon {
        transition: none !important;
    }
}

/* 14-menu-system.css */
/*
 * Top-menu system: every entry shares one paper/workbench shell.
 * Individual menus keep their native information architecture; this layer only
 * establishes the common material, edge, type colour and scrolling language.
 */

/* 宿主在1000px以下提前全屏化抽屉；本主题阅读平面到700px才全宽。
 * 统一中间菜单的外框，不改变内部排版或原生展开/关闭状态。
 */
@media (min-width: 701px) {
    #top-settings-holder > .drawer > .drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
        width: min(var(--sheldWidth), 1080px) !important;
        min-width: 0 !important;
        max-width: 1080px !important;
        left: 0 !important;
        right: 0 !important;
        margin-inline: auto !important;
    }

    /* 恢复宿主fillLeft/fillRight的剩余空间公式，而不是写死295px。
     * 1184px/50%时295px；890px/50%时221.5px。最大化仍交给宿主。
     */
    #top-settings-holder > .drawer > :is(#left-nav-panel, #right-nav-panel):not(.maximized) {
        width: max(100px, calc((100dvw - min(var(--sheldWidth), 1080px) - 2px) / 2)) !important;
        min-width: 100px !important;
        max-width: none !important;
        margin-inline: 0 !important;
    }

    #top-settings-holder > .drawer > #left-nav-panel:not(.maximized) {
        left: 0 !important;
        right: auto !important;
    }

    #top-settings-holder > .drawer > #right-nav-panel:not(.maximized) {
        left: auto !important;
        right: 0 !important;
    }
}

#top-settings-holder > .drawer > .drawer-content {
    --SmartThemeBodyColor: var(--ef-ink) !important;
    --SmartThemeEmColor: #5f6765 !important;
    --SmartThemeBlurTintColor: rgba(253, 253, 253, 0.985) !important;
    --SmartThemeBorderColor: rgba(23, 26, 26, 0.22) !important;
    --SmartThemeShadowColor: transparent !important;
    box-sizing: border-box;
    color: var(--ef-ink) !important;
    background-color: var(--ef-paper) !important;
    background-image: var(--ef-paper-grid) !important;
    background-size: 160px 160px !important;
    background-position: 0 0 !important;
    background-repeat: repeat !important;
    border: 1px solid rgba(23, 26, 26, 0.28) !important;
    border-top: 3px solid var(--ef-void) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#top-settings-holder > .drawer > .drawer-content * {
    text-shadow: none !important;
}

#top-settings-holder > .drawer > .drawer-content:not(#user-settings-block) :is(h2, h3) {
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-display) !important;
    font-weight: 700 !important;
    letter-spacing: 0.005em;
}

#top-settings-holder > .drawer > .drawer-content:not(#user-settings-block) h4,
#top-settings-holder > .drawer > #rm_api_block #title_api {
    color: var(--ef-graphite) !important;
    font-family: var(--ef-font-body) !important;
    font-size: calc(var(--mainFontSize) * 0.9) !important;
    font-weight: 650 !important;
    line-height: 1.35;
    letter-spacing: 0.01em;
}

/*
 * Internal hierarchy: remove SillyTavern's glossy capsule language.  Section
 * bars, fold rows and notices read as flat archive furniture, while retaining
 * the native order and hit targets of every menu.
 */
#top-settings-holder > .drawer > .drawer-content:not(#user-settings-block) .standoutHeader {
    position: relative;
    box-sizing: border-box;
    min-height: 28px;
    padding: 4px 7px 4px 9px !important;
