}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) {
    --ef-cover-board: #fff;
    --ef-cover-ink: #151818;
    --ef-cover-label: #535b50;
    --ef-cover-muted: #707767;
    --ef-cover-meta-gap: clamp(10px, 3.5cqw, 18px);
    --ef-cover-meta-size: clamp(10px, 2.3cqw, 11px);
    --ef-cover-photo-size: 103cqw;
    --ef-cover-title-size: 8.1cqw;
    --ef-cover-index-size: clamp(20px, 5.2cqw, 30px);
    --ef-cover-index-edge: clamp(4px, calc(var(--ef-cover-index-size) * .27), 8px);
    --ef-cover-index-height: calc(var(--ef-cover-index-size) * .9 + 8px + var(--ef-cover-index-edge));
