}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > :not(.ch_name, .mes_reasoning_details, .mes_text, .mes_media_wrapper, .mes_file_wrapper) {
    grid-area: extra / 2 / actions / 6;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .mes_text {
    min-width: 0;
    margin: 0 !important;
    padding: 18px 5cqw 16px !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > :is(.for_checkbox, .del_checkbox) {
    position: absolute;
    z-index: 5;
    top: 18px;
    right: 4cqw;
    margin: 0 !important;
}

/* 窄屏把 GEN 与 TOK 一起移到日期下方；原生空值/隐藏时轨道仍自然收缩。 */
@container ef-chat (max-width: 359px) {
    body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) {
        grid-template-rows: [photo] auto [name] max-content [meta] auto [meta-counts] auto [reasoning] auto [reply] auto [media] auto [file] auto [extra] auto [actions] auto [end];
    }
}
@container ef-chat (max-width: 359px) {
    body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .ch_name .timestamp {
        grid-area: meta / 2 / meta-counts / 5;
        padding-right: 0;
        padding-bottom: var(--ef-cover-bottom-gap);
        white-space: normal;
        overflow-wrap: anywhere;
    }
    body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper > .mes_timer {
        grid-area: meta-counts / 2 / reasoning / 3;
        padding-top: 0;
    }
    body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mesAvatarWrapper > .tokenCounterDisplay {
        grid-area: meta-counts / 3 / reasoning / 4;
        padding-top: 0;
    }
    body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .ch_name :is(.timestamp-icon, .mes_ghost) { grid-area: meta-counts / 4 / reasoning / 5; }
}

/* 17-cover-reasoning.css */
/*
 * 封面推理分区。16-message-cover 提供父网格；本模块仅占 mes_block 第 3 行。
 * 官方原图量值：灰带 6.3% 消息宽，实字顶部距带顶 2.4%，浅纸面延续 6.4%。
 * 完整 ENDFIELD 轮廓来自已确认的交互稿，避开系统字体度量变化。
 * 不指定 details/正文/actions 的 display；空推理、编辑及隐藏推理由宿主控制。
 */

@property --ef-reasoning-stop-a {
    syntax: "<percentage>";
    inherits: false;
    initial-value: 0%;
}

@property --ef-reasoning-stop-b {
    syntax: "<percentage>";
    inherits: false;
    initial-value: 70%;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) {
    --ef-reasoning-band-height: 6.3cqw;
    --ef-reasoning-word-top: 2.4cqw;
    --ef-reasoning-word-size: 16cqw;
    --ef-reasoning-pale-height: 6.4cqw;
    --ef-reasoning-wordmark: url("data:image/svg+xml;base64,");
    --ef-reasoning-paper-start: #eeeeee;
    --ef-reasoning-paper-end: #f5f6f3;
    --ef-reasoning-reply-paper: #ffffff;
    --ef-reasoning-pale-ink: #e4e4e4;
}

/* 两个网格伪元素常驻；没有推理时，第 3 行仍由灰带自身撑起。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block::before,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block::after {
    content: "" !important;
    display: block !important;
    grid-area: reasoning / 1 / reply / -1;
    align-self: start;
    justify-self: stretch;
    position: relative !important;
    inset: auto !important;
    box-sizing: border-box;
    width: 100% !important;
    height: var(--ef-reasoning-band-height) !important;
    min-width: 0;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    opacity: 1 !important;
    transform: none !important;
    animation: none !important;
    pointer-events: none !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block::before {
    z-index: 0;
    background: #d0d0d0 !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block::after {
    z-index: 1;
    background: repeating-linear-gradient(135deg, #b3b3b3 0 1px, transparent 1px 3px) !important;
    -webkit-mask-image: var(--ef-reasoning-wordmark) !important;
    mask-image: var(--ef-reasoning-wordmark) !important;
    -webkit-mask-size: 100cqw var(--ef-reasoning-word-size) !important;
    mask-size: 100cqw var(--ef-reasoning-word-size) !important;
    -webkit-mask-position: 5cqw var(--ef-reasoning-word-top) !important;
    mask-position: 5cqw var(--ef-reasoning-word-top) !important;
    -webkit-mask-repeat: no-repeat !important;
    mask-repeat: no-repeat !important;
}

/* 色条属于封面边界；与 details 的有无、折叠或编辑无关。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .ch_name::after,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .ch_name:has(~ .mes_reasoning_details)::after {
    content: "" !important;
    display: block !important;
    grid-area: reasoning / 1 / reply / -1;
    align-self: start;
    justify-self: start;
    position: relative !important;
    inset: auto !important;
    z-index: 4;
    width: 56% !important;
    height: 2px !important;
    margin: 0 0 0 5% !important;
    padding: 0 !important;
    background: linear-gradient(to right, var(--ef-calib-m) 0 23%, var(--ef-calib-y) 23% 43%, var(--ef-calib-c) 43% 100%) !important;
    background-size: 100% 2px !important;
    opacity: 1 !important;
    transform: translateY(-2px) !important;
    animation: none !important;
    pointer-events: none !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .mes_reasoning_details {
    grid-area: reasoning / 1 / reply / -1;
    align-self: start;
    position: relative;
    z-index: 2;
    isolation: isolate;
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
}

/* 移除旧深色标题块、第二条色线与黑色页脚。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_summary::after,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_header::before,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_header::after,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_header_title::before,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details::after {
    content: none !important;
    display: none !important;
    animation: none !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_summary {
    position: static !important;
    box-sizing: border-box;
    width: 100%;
    height: var(--ef-reasoning-band-height);
    min-height: 0;
    margin: 0 !important;
    padding: 0 !important;
    gap: 0 !important;
    flex-wrap: nowrap !important;
    align-items: stretch !important;
    list-style: none;
    background: transparent !important;
    border: 0 !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_summary:focus-visible {
    outline: 1px solid #596154;
    outline-offset: -3px;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_header_block {
    position: static !important;
    flex: 1 1 100% !important;
    width: 100%;
    height: 100%;
    min-width: 0;
    margin: 0 !important;
    padding: 0 !important;
}

/* 宿主仅允许从 header 内触发折叠，故实际点击区铺满灰带。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_summary .mes_reasoning_header {
    position: relative !important;
    align-self: stretch !important;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    min-height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    color: #656b63 !important;
    background: transparent !important;
    box-shadow: none !important;
}

/* 只做视觉隐藏，读屏仍能读到宿主更新的思考状态与耗时。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_summary .mes_reasoning_header_title {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    min-width: 0 !important;
    margin: -1px !important;
    padding: 0 !important;
    overflow: hidden !important;
    clip-path: inset(50%) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_summary .mes_reasoning_arrow {
    position: absolute !important;
    top: 42% !important;
    right: 5% !important;
    width: 7px !important;
    height: 7px !important;
    margin: 0 !important;
    border: solid #656b63 !important;
    border-width: 0 1px 1px 0 !important;
    color: transparent !important;
    font-size: 0 !important;
    transform: rotate(45deg) !important;
    transition: border-color 150ms ease;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details[open] .mes_reasoning_arrow {
    top: 51% !important;
    transform: rotate(225deg) !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_arrow::before {
    content: none !important;
}

@media (hover: hover) {
    body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_header:hover .mes_reasoning_arrow {
        border-color: #323b2a !important;
    }
}

/* 旧 11 的 display: inline-flex !important 曾盖住宿主编辑态隐藏规则。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details:has(> .reasoning_edit_textarea) .mes_reasoning_header {
    display: none !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details[open]:has(> :is(.mes_reasoning:not(:empty), .reasoning_edit_textarea)) {
    padding-bottom: 36px !important;
    background: linear-gradient(to bottom, transparent 0 var(--ef-reasoning-band-height), var(--ef-reasoning-paper-start) var(--ef-reasoning-band-height), var(--ef-reasoning-paper-end) calc(var(--ef-reasoning-band-height) + var(--ef-reasoning-pale-height))) !important;
    border-bottom: 1px solid #e0e3dd !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_actions {
    position: absolute !important;
    z-index: 3;
    right: 5%;
    bottom: 7px;
    left: auto;
    top: auto;
    max-width: 90%;
    margin: 0 !important;
    gap: 6px;
    flex-wrap: wrap;
    justify-content: flex-end;
    color: #66705e !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details > .mes_reasoning {
    position: relative;
    z-index: 1;
    margin: 0 !important;
    padding: 18px 5% 12px !important;
    color: #626c58 !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    animation: none !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details > .reasoning_edit_textarea {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    width: 90%;
    margin: 18px 5% 12px;
}

/* 浅纸面中的同一个字标继续向下，不另起第二个 ENDFIELD。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details[open]:has(> :is(.mes_reasoning:not(:empty), .reasoning_edit_textarea))::before,
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .mes_text::before {
    content: "" !important;
    position: absolute !important;
    z-index: 0;
    left: 0;
    right: auto;
    width: 100%;
    height: var(--ef-reasoning-pale-height);
    margin: 0;
    background: repeating-linear-gradient(135deg, var(--ef-reasoning-pale-ink) 0 1px, transparent 1px 3px);
    opacity: 0.45;
    -webkit-mask-image: var(--ef-reasoning-wordmark);
    mask-image: var(--ef-reasoning-wordmark);
    -webkit-mask-size: 100cqw var(--ef-reasoning-word-size);
    mask-size: 100cqw var(--ef-reasoning-word-size);
    -webkit-mask-position: 5cqw calc(var(--ef-reasoning-word-top) - var(--ef-reasoning-band-height));
    mask-position: 5cqw calc(var(--ef-reasoning-word-top) - var(--ef-reasoning-band-height));
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    pointer-events: none !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) .mes_reasoning_details[open]::before {
    top: var(--ef-reasoning-band-height);
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .mes_text {
    position: relative;
    isolation: isolate;
    /* 18-reading-paper 在 reply→end 轨道绘制连续纸面。 */
    background: transparent !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) > .mes_block > .mes_text::before {
    top: 0;
    z-index: -1;
}

/* 仅真正可见的展开内容接浅纸；被宿主隐藏的空 details 不改变正文顶部。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes.reasoning:not(.smallSysMes):has(> .mes_block > .mes_reasoning_details[open] > :is(.mes_reasoning:not(:empty), .reasoning_edit_textarea)) > .mes_block > .mes_text {
    background: transparent !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes.reasoning:not(.smallSysMes):has(> .mes_block > .mes_reasoning_details[open] > :is(.mes_reasoning:not(:empty), .reasoning_edit_textarea)) > .mes_block > .mes_text::before {
    content: none !important;
}

/* 用户正文接浅灰纸面；灰带与字标的位置继续和 AI 消息共用。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes[is_user="true"]:not(.smallSysMes) {
    --ef-reasoning-paper-start: #e7eae4;
    --ef-reasoning-paper-end: #e7eae4;
    --ef-reasoning-reply-paper: #e7eae4;
    --ef-reasoning-pale-ink: #d2d8cd;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes[is_user="true"]:not(.smallSysMes) .mes_reasoning_details > .mes_reasoning {
    color: #626c58 !important;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes[is_user="true"]:not(.smallSysMes) .mes_reasoning_actions {
    color: #66705e !important;
}

/* 只有宿主真实 thinking 状态驱动；完成后立即回到静态 M/Y/C 套准线。 */
@media (prefers-reduced-motion: no-preference) {
    body:not(.hideChatAvatars):not(.documentstyle):not(.reduced-motion) #chat > .mes:not(.smallSysMes):is([data-reasoning-state="thinking"], :has(> .mes_block > .mes_reasoning_details[data-state="thinking"])) > .mes_block > .ch_name::after {
        background-image: linear-gradient(to right,
            var(--ef-reasoning-color-a, var(--ef-calib-c)) 0 var(--ef-reasoning-stop-a),
            var(--ef-reasoning-color-b, var(--ef-calib-m)) var(--ef-reasoning-stop-a) var(--ef-reasoning-stop-b),
            var(--ef-reasoning-color-c, var(--ef-calib-y)) var(--ef-reasoning-stop-b) 100%) !important;
        animation: ef-cover-reasoning-calibration-run 1800ms linear infinite !important;
    }
}

@keyframes ef-cover-reasoning-calibration-run {
    0% {
        --ef-reasoning-stop-a: 0%;
        --ef-reasoning-stop-b: 70%;
        --ef-reasoning-color-a: var(--ef-calib-c);
        --ef-reasoning-color-b: var(--ef-calib-m);
        --ef-reasoning-color-c: var(--ef-calib-y);
        animation-timing-function: cubic-bezier(0.25, 0.3, 0.65, 0.82);
    }
    33.32% {
        --ef-reasoning-stop-a: 70%;
        --ef-reasoning-stop-b: 100%;
        --ef-reasoning-color-a: var(--ef-calib-c);
        --ef-reasoning-color-b: var(--ef-calib-m);
        --ef-reasoning-color-c: var(--ef-calib-y);
        animation-timing-function: steps(1, end);
    }
    33.34% {
        --ef-reasoning-stop-a: 0%;
        --ef-reasoning-stop-b: 70%;
        --ef-reasoning-color-a: var(--ef-calib-y);
        --ef-reasoning-color-b: var(--ef-calib-c);
        --ef-reasoning-color-c: var(--ef-calib-m);
        animation-timing-function: cubic-bezier(0.25, 0.3, 0.65, 0.82);
    }
    66.65% {
        --ef-reasoning-stop-a: 70%;
        --ef-reasoning-stop-b: 100%;
        --ef-reasoning-color-a: var(--ef-calib-y);
        --ef-reasoning-color-b: var(--ef-calib-c);
        --ef-reasoning-color-c: var(--ef-calib-m);
        animation-timing-function: steps(1, end);
    }
    66.67% {
        --ef-reasoning-stop-a: 0%;
        --ef-reasoning-stop-b: 70%;
        --ef-reasoning-color-a: var(--ef-calib-m);
        --ef-reasoning-color-b: var(--ef-calib-y);
        --ef-reasoning-color-c: var(--ef-calib-c);
        animation-timing-function: cubic-bezier(0.25, 0.3, 0.65, 0.82);
    }
    99.98% {
        --ef-reasoning-stop-a: 70%;
        --ef-reasoning-stop-b: 100%;
        --ef-reasoning-color-a: var(--ef-calib-m);
        --ef-reasoning-color-b: var(--ef-calib-y);
        --ef-reasoning-color-c: var(--ef-calib-c);
        animation-timing-function: steps(1, end);
    }
    100% {
        --ef-reasoning-stop-a: 0%;
        --ef-reasoning-stop-b: 70%;
        --ef-reasoning-color-a: var(--ef-calib-c);
        --ef-reasoning-color-b: var(--ef-calib-m);
        --ef-reasoning-color-c: var(--ef-calib-y);
    }
}

/* 17-site-surfaces.css */
/*
 * 官网质感第一步（2026-09-06）：参照 endfield.hypergryph.com/operator。
 * 外底纹理在下部显现；可点击条目轻抬，不改变阅读面与消息封面。
 * 官网卡片约 200ms 上移；宿主连续列表间距更紧，位移限为 1px。
 */

body {
    /* 用同色遮层收住上半部网格，保留底部的制图纹理。
     * 两层固定在视口上，滚动长聊天时不会反复出现整块渐变接缝。
     */
    background-image:
        linear-gradient(
            180deg,
            var(--ef-workbench) 0%,
            var(--ef-workbench) 30%,
            rgba(229, 229, 229, 0.94) 44%,
            rgba(229, 229, 229, 0.52) 72%,
            rgba(229, 229, 229, 0.12) 100%
        ),
        var(--ef-gray-grid) !important;
    background-size: 100% 100%, 160px 160px !important;
    background-position: center, 0 0 !important;
    background-repeat: no-repeat, repeat !important;
    background-attachment: fixed, fixed !important;
}

/* 仅桌面鼠标产生位移。保留宿主批量选择、键盘聚焦及触屏行为。 */
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
    body:not(.reduced-motion) #rm_print_characters_block:not(.bulk_select):not(.group_overlay_mode_select) > .character_select {
        transition:
            transform 200ms ease,
            background-color var(--ef-fast) ease-out,
            box-shadow 200ms ease !important;
    }

    body:not(.reduced-motion) #rm_print_characters_block:not(.bulk_select):not(.group_overlay_mode_select) > .character_select:hover {
        transform: translateY(-1px);
        box-shadow: 0 2px 3px rgba(23, 26, 26, 0.1) !important;
    }
}

/* 18-reading-paper.css */
/* 公告纸面定稿：外部网格不变；正文、媒体与尾部操作共享纸面。
 * 装饰只占现有 reply→end 轨道，不产生高度，不拦截点击。
 * SVG 与官方点阵随构建嵌入；维护素材位于 src/assets/reading/。
 */

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes) {
    --ef-reading-paper: #fff;
    --ef-reading-contour-rt: url("data:image/svg+xml;base64,");
    --ef-reading-contour-lb: url("data:image/svg+xml;base64,");
    --ef-reading-dots: url("data:image/png;base64,");
    isolation: isolate;
}

body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes[is_user="true"]:not(.smallSysMes) {
    --ef-reading-paper: #e7eae4;
}

/* 两个角各限于半张阅读面；短回复等比收小，长回复达到素材定稿尺寸。 */
body:not(.hideChatAvatars):not(.documentstyle) #chat > .mes:not(.smallSysMes)::after {
    content: "";
