#chat > .welcomePanel .recentChat .characterName::after {
    content: "";
    position: absolute;
    right: 10px;
    top: 50%;
    width: 8px;
    height: 20px;
    background: #858585;
    clip-path: polygon(0 0, 25% 0, 25% 100%, 0 100%);
    transform: translate(0, -50%);
    transition: clip-path .2s ease, transform .2s ease, background-color .2s ease;
    pointer-events: none;
