/* 21-scrollbars.css */
/* Shared native scrollbar: 5px flat body, distinct rim, quiet shadow, fixed caps.
 * The 16px paint area includes transparent shadow space. An even paint width keeps common device scales on whole pixels. No scroll driver,
 * overflow or resize changes; intentionally hidden bars remain hidden.
 */
:root,
:root :not(.no-scrollbar) {
    --ef-sb-fallback: #9d9696;
    --ef-sb-rail: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxNiIgaGVpZ2h0PSIxIiB2aWV3Qm94PSIwLjUgMCAxNiAxIiBwcmVzZXJ2ZUFzcGVjdFJhdGlvPSJub25lIj4KPHJlY3QgeD0iNy41IiB5PSIwIiB3aWR0aD0iMiIgaGVpZ2h0PSIxIiBmaWxsPSIjZDVkMGQwIi8+Cjwvc3ZnPgo=");
    --ef-sb-cross-rail: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxIiBoZWlnaHQ9IjE2IiB2aWV3Qm94PSIwIDAuNSAxIDE2IiBwcmVzZXJ2ZUFzcGVjdFJhdGlvPSJub25lIj4KPHJlY3QgeD0iMCIgeT0iNy41IiB3aWR0aD0iMSIgaGVpZ2h0PSIyIiBmaWxsPSIjZDVkMGQwIi8+Cjwvc3ZnPgo=");
    --ef-sb-cap-start: url("data:image/svg+xml;base64,");
    --ef-sb-cap-end: url("data:image/svg+xml;base64,");
    --ef-sb-shaft: url("data:image/svg+xml;base64,");
    --ef-sb-cap-left: url("data:image/svg+xml;base64,");
    --ef-sb-cap-right: url("data:image/svg+xml;base64,");
    --ef-sb-cross-shaft: url("data:image/svg+xml;base64,");
}

/* This outer settings scroller has a dark shell. Its light descendants get
 * their own light defaults above, rather than inheriting the dark thumb. */
#user-settings-block {
    --ef-sb-fallback: #aaa4a4;
    --ef-sb-rail: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxNiIgaGVpZ2h0PSIxIiB2aWV3Qm94PSIwLjUgMCAxNiAxIiBwcmVzZXJ2ZUFzcGVjdFJhdGlvPSJub25lIj4KPHJlY3QgeD0iNy41IiB5PSIwIiB3aWR0aD0iMiIgaGVpZ2h0PSIxIiBmaWxsPSIjNTc1NDU0Ii8+Cjwvc3ZnPgo=");
    --ef-sb-cross-rail: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxIiBoZWlnaHQ9IjE2IiB2aWV3Qm94PSIwIDAuNSAxIDE2IiBwcmVzZXJ2ZUFzcGVjdFJhdGlvPSJub25lIj4KPHJlY3QgeD0iMCIgeT0iNy41IiB3aWR0aD0iMSIgaGVpZ2h0PSIyIiBmaWxsPSIjNTc1NDU0Ii8+Cjwvc3ZnPgo=");
    --ef-sb-cap-start: url("data:image/svg+xml;base64,");
    --ef-sb-cap-end: url("data:image/svg+xml;base64,");
    --ef-sb-shaft: url("data:image/svg+xml;base64,");
    --ef-sb-cap-left: url("data:image/svg+xml;base64,");
    --ef-sb-cap-right: url("data:image/svg+xml;base64,");
    --ef-sb-cross-shaft: url("data:image/svg+xml;base64,");
}

/* Non-auto standard properties would suppress Blink's detailed pseudo styles.
 * Normalize only known native rules, preserving editor/extension hide rules. */
@supports selector(::-webkit-scrollbar) {
:root,
body,
.scrollable-buttons-container,
.streaming-display-reasoning-content,
.streaming-display-text-content {
    scrollbar-color: auto;
    scrollbar-width: auto;
}
}

/* Let forced-colors retain the host's native colors and hidden-scrollbar rules. */
@media (forced-colors: none) {
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar {
    width: 16px;
    height: 16px;
    background: transparent;
}
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-track:vertical {
    /* Match the thumb's SVG canvas and viewBox. A separate 2px background
     * rounds to five opaque pixels at DPR 2.5 and shifts its axis by half a pixel. */
    background: var(--ef-sb-rail) center / 16px 100% no-repeat;
}
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-track:horizontal {
    background: var(--ef-sb-cross-rail) center / 100% 16px no-repeat;
}
/* Both directions explicitly clear the host's 2px border, 40px minimum and
 * movingUI top border. Only the uniform SVG shaft stretches along its axis. */
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-thumb:vertical,
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-thumb:horizontal {
    min-height: 28px;
    min-width: 28px;
    border: 0;
    border-radius: 0;
    background:
        var(--ef-sb-cap-start) center top / 16px 14px no-repeat,
        var(--ef-sb-cap-end) center bottom / 16px 14px no-repeat,
        var(--ef-sb-shaft) center / 16px calc(100% - 28px) no-repeat;
    background-clip: border-box;
    box-shadow: none;
}
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-thumb:horizontal {
    background:
        var(--ef-sb-cap-left) left center / 14px 16px no-repeat,
        var(--ef-sb-cap-right) right center / 14px 16px no-repeat,
        var(--ef-sb-cross-shaft) center / calc(100% - 28px) 16px no-repeat;
}
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-corner { background: transparent; }
:is(:root, :root :not(.no-scrollbar))::-webkit-scrollbar-button { display: none; width: 0; height: 0; }
}

@supports not selector(::-webkit-scrollbar) {
    :where(:root, :root :not(.no-scrollbar)) {
        scrollbar-width: thin;
        scrollbar-color: var(--ef-sb-fallback) transparent;
    }
}
@media (forced-colors: active) {
    :where(:root, :root :not(.no-scrollbar)) { scrollbar-width: auto; scrollbar-color: auto; }
}

