        --source-pixel: clamp(.125px, .02604167vw, .5px);
        --paper-color: #fefcfd;
        --button-width: clamp(196px, 16vw, 305px);
        --button-height: clamp(40px, 3.268vw, 62px);
        --button-gap: clamp(20px, 1.65vw, 32px);
