        position: fixed;
        inset: 0;
        width: 100%;
        max-width: none;
        min-width: 0;
        min-height: 0;
        height: fit-content;
        max-height: calc(100dvh - 64px);
        margin: auto;
        padding: 0;
        border: 0;
        border-radius: 0;
